'use client'

import { useCallback, useState } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { CaptionsIcon, DownloadIcon, SparklesIcon, Trash2Icon } from '@/lib/icons'
import { toast } from 'sonner'
import { extractAudioToWav } from '@mcut/media'
import { useEditor, useProject, usePlayback } from '@mcut/react'
import {
  CAPTION_STYLE_PRESETS,
  isElementActiveAt,
  type CaptionElement,
  type CaptionStylePreset,
  type ElementAudioSource,
  type ElementId,
  type Project,
  resolveElementAudioSource,
} from '@mcut/timeline'
import { buildApplyCaptionsCommand, toSrt, toVtt, type SubtitleCue, type TranscriptResult } from '@mcut/transcription'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { ScrollArea } from '@/components/ui/scroll-area'
import { Switch } from '@/components/ui/switch'
import { Textarea } from '@/components/ui/textarea'
import { EmptyState, PanelHeader, PanelSectionLabel, Spinner } from './editor-primitives'
import { formatTimecode } from './format'
import { defaultModelDownloadLabel, isLocalTranscriptionSupported, setOnDeviceTranscriptionEnabled, useOnDeviceTranscription } from './local-transcription'
import { host, type TranscriptionSettings } from './studio-host'

export interface CaptionsPanelProps {
  className?: string
  transcribe?: (audio: Blob) => Promise<TranscriptResult>
}

function captionsOf(project: Project): CaptionElement[] {
  return project.tracks
    .flatMap((track) => track.elements)
    .filter((e): e is CaptionElement => e.type === 'caption')
    .sort((a, b) => a.startMs - b.startMs)
}

function pickTranscriptionSource(project: Project, selectedElementIds: readonly string[]): ElementAudioSource | null {
  for (const elementId of selectedElementIds) {
    const source = resolveElementAudioSource(project, elementId as ElementId)
    if (source) return source
  }

  return (
    project.tracks
      .flatMap((track) => track.elements)
      .sort((a, b) => a.startMs - b.startMs)
      .map((element) => resolveElementAudioSource(project, element.id))
      .find((source): source is ElementAudioSource => source !== null) ?? null
  )
}

function downloadText(filename: string, text: string, type: string) {
  const url = URL.createObjectURL(new Blob([text], { type }))
  const anchor = document.createElement('a')
  anchor.href = url
  anchor.download = filename
  anchor.click()
  URL.revokeObjectURL(url)
}

function retypedTextWithoutWordTimings(text: string): Pick<CaptionElement, 'text' | 'words'> {
  return { text, words: [] }
}

function CaptionRow({ caption }: { caption: CaptionElement }) {
  const engine = useEditor()
  const active = usePlayback((s) => isElementActiveAt(caption, s.currentTimeMs))
  const isPlaying = usePlayback((s) => s.isPlaying)

  const followPlayhead = useCallback(
    (node: HTMLDivElement | null) => {
      if (node && active && isPlaying) {
        node.scrollIntoView({ block: 'nearest', behavior: 'smooth' })
      }
    },
    [active, isPlaying],
  )

  return (
    <div ref={followPlayhead} className={cn('group flex flex-col gap-1 rounded-lg p-2 transition-colors hover:bg-muted/60', active && 'bg-primary/10')}>
      <div className="flex items-center gap-1">
        <button
          type="button"
          className="cursor-pointer font-mono text-2xs text-muted-foreground hover:text-foreground"
          title="Seek to caption"
          onClick={() => engine.seek(caption.startMs)}
        >
          {formatTimecode(caption.startMs)} – {formatTimecode(caption.startMs + caption.durationMs)}
        </button>
        <div className="flex-1" />
        <Button
          variant="ghost"
          size="icon-xs"
          title="Delete caption"
          className="opacity-0 transition-opacity group-focus-within:opacity-100 group-hover:opacity-100"
          onClick={() => engine.dispatch({ type: 'removeElement', elementId: caption.id })}
        >
          <Trash2Icon />
        </Button>
      </div>
      <Textarea
        value={caption.text}
        rows={1}
        className="min-h-7 resize-none border-transparent bg-transparent p-1 text-xs shadow-none focus-visible:border-transparent focus-visible:bg-input/50 focus-visible:ring-0"
        onChange={(event) => {
          try {
            engine.dispatch({
              type: 'updateElement',
              elementId: caption.id,
              patch: retypedTextWithoutWordTimings(event.target.value),
            })
          } catch {}
        }}
      />
    </div>
  )
}

function OnDeviceToggle() {
  const enabled = useOnDeviceTranscription()
  if (!isLocalTranscriptionSupported()) return null
  return (
    <label className="flex items-center justify-between gap-2 text-xs text-muted-foreground">
      <span title={`Runs Whisper in your browser — audio never leaves this device. One-time ${defaultModelDownloadLabel()} model download, cached afterwards.`}>
        Transcribe on this device
      </span>
      <Switch checked={enabled} onCheckedChange={setOnDeviceTranscriptionEnabled} />
    </label>
  )
}

const TRANSCRIPTION_KEY_QUERY = ['mcut', 'transcription-key'] as const

function TranscriptionKeyField({ settings }: { settings: TranscriptionSettings }) {
  const [key, setKey] = useState('')
  const queryClient = useQueryClient()
  const configured = useQuery({ queryKey: TRANSCRIPTION_KEY_QUERY, queryFn: () => settings.isConfigured(), staleTime: Infinity })
  const save = useMutation({
    mutationFn: (value: string) => settings.setKey(value),
    onSuccess: (isConfigured) => {
      queryClient.setQueryData(TRANSCRIPTION_KEY_QUERY, isConfigured)
      setKey('')
      toast.success(isConfigured ? 'AssemblyAI key saved' : 'AssemblyAI key removed')
    },
  })
  const isConfigured = configured.data === true
  return (
    <div className="flex flex-col gap-1.5">
      <div className="flex items-center justify-between gap-2 text-xs text-muted-foreground">
        <span>AssemblyAI API key</span>
        {isConfigured && <span className="text-2xs font-medium text-foreground">Configured</span>}
      </div>
      <div className="flex gap-1.5">
        <Input
          aria-label="AssemblyAI API key"
          type="password"
          autoComplete="off"
          className="h-7 text-xs"
          placeholder={isConfigured ? 'Paste a new key to replace it' : 'Paste your AssemblyAI API key'}
          value={key}
          onChange={(event) => setKey(event.target.value)}
        />
        <Button variant="outline" size="xs" disabled={key.trim().length === 0 || save.isPending} onClick={() => save.mutate(key)}>
          Save
        </Button>
        {isConfigured && (
          <Button variant="ghost" size="xs" disabled={save.isPending} onClick={() => save.mutate('')}>
            Remove
          </Button>
        )}
      </div>
      <p className="text-2xs text-muted-foreground">
        Stored by the desktop app with the system keychain. On Linux without a keyring it is only obfuscated, not encrypted.
      </p>
    </div>
  )
}

function CaptionStylePresets({ captions }: { captions: CaptionElement[] }) {
  const engine = useEditor()
  const apply = (preset: CaptionStylePreset) => {
    engine.transact(() => {
      for (const caption of captions) {
        const style = { ...caption.style, ...preset.style }
        if (!('activeWordColor' in preset.style)) delete style.activeWordColor
        try {
          engine.dispatch({
            type: 'updateElement',
            elementId: caption.id,
            patch: { style },
          })
        } catch {}
      }
    })
  }
  return (
    <div className="flex flex-col gap-1">
      <PanelSectionLabel>Style</PanelSectionLabel>
      <div className="grid grid-cols-3 gap-1.5">
        {CAPTION_STYLE_PRESETS.map((preset) => (
          <Button
            key={preset.id}
            variant="outline"
            size="xs"
            title={preset.style.activeWordColor ? `${preset.label} (highlights the spoken word)` : preset.label}
            onClick={() => apply(preset)}
          >
            {preset.label}
          </Button>
        ))}
      </div>
    </div>
  )
}

export function CaptionsPanel({ className, transcribe }: CaptionsPanelProps) {
  const engine = useEditor()
  const project = useProject()
  const captions = captionsOf(project)

  const transcription = useMutation({
    mutationFn: async () => {
      if (!transcribe) {
        throw new Error('No transcribe handler configured.')
      }
      const source = pickTranscriptionSource(engine.project, engine.selection.elementIds)
      if (!source) {
        throw new Error('Add a video or audio clip to the timeline first.')
      }
      const wav = await extractAudioToWav(source.asset.src)
      if (!wav) {
        throw new Error(`"${source.asset.name ?? source.asset.id}" has no audio track.`)
      }
      const result = await transcribe(wav)
      return { result, source }
    },
    onSuccess: ({ result, source }) => {
      engine.dispatch(
        buildApplyCaptionsCommand(result, {
          timeOffsetMs: source.timelineStartMs,
          sourceStartMs: source.sourceStartMs,
          sourceEndMs: source.sourceEndMs,
        }),
      )
      toast.success('Captions added to the timeline')
    },
    onError: (error) => {
      toast.error(error instanceof Error ? error.message : 'Transcription failed')
    },
  })

  const cues = (): SubtitleCue[] =>
    captionsOf(engine.project).map((c) => ({
      startMs: c.startMs,
      endMs: c.startMs + c.durationMs,
      text: c.text,
    }))

  return (
    <div className={cn('flex h-full min-h-0 flex-col', className)}>
      <PanelHeader>
        <PanelSectionLabel>Captions</PanelSectionLabel>
      </PanelHeader>
      <div className="flex shrink-0 flex-col gap-3 px-3 pb-3">
        <Button className="w-full" disabled={transcription.isPending || !transcribe} onClick={() => transcription.mutate()}>
          {transcription.isPending ? <Spinner /> : <SparklesIcon />}
          {transcription.isPending ? 'Transcribing…' : 'Auto-caption'}
        </Button>
        {!transcribe && (
          <p className="text-xs text-muted-foreground">
            Pass a <code className="font-mono">transcribe</code> handler to enable auto-captions.
          </p>
        )}
        <OnDeviceToggle />
        {host.transcriptionSettings && <TranscriptionKeyField settings={host.transcriptionSettings} />}

        {captions.length > 0 && (
          <>
            <CaptionStylePresets captions={captions} />
            <div className="flex gap-2">
              <Button variant="outline" size="xs" className="flex-1" onClick={() => downloadText(`${project.name}.srt`, toSrt(cues()), 'application/x-subrip')}>
                <DownloadIcon /> SRT
              </Button>
              <Button variant="outline" size="xs" className="flex-1" onClick={() => downloadText(`${project.name}.vtt`, toVtt(cues()), 'text/vtt')}>
                <DownloadIcon /> VTT
              </Button>
            </div>
            <PanelSectionLabel>Transcript · {captions.length}</PanelSectionLabel>
          </>
        )}
      </div>

      {captions.length === 0 ? (
        <EmptyState className="mx-3 mb-3 flex-1" icon={CaptionsIcon} description="No captions yet. Import media, then auto-caption it." />
      ) : (
        <ScrollArea className="min-h-0 flex-1 scroll-mask-b">
          <div className="flex flex-col gap-1 px-3 pb-3">
            {captions.map((caption) => (
              <CaptionRow key={caption.id} caption={caption} />
            ))}
          </div>
        </ScrollArea>
      )}
    </div>
  )
}

export function formatTimecode(ms: number): string {
  const total = Math.max(0, ms)
  const minutes = Math.floor(total / 60_000)
  const seconds = Math.floor((total % 60_000) / 1000)
  const tenths = Math.floor((total % 1000) / 100)
  return `${minutes}:${String(seconds).padStart(2, '0')}.${tenths}`
}

export function formatRulerLabel(ms: number): string {
  const minutes = Math.floor(ms / 60_000)
  const seconds = Math.round((ms % 60_000) / 1000)
  return `${minutes}:${String(seconds).padStart(2, '0')}`
}

export function formatDurationBadge(ms: number): string {
  return formatRulerLabel(Math.round(ms / 1000) * 1000)
}

'use client'

import * as React from 'react'
import { spinners } from 'unicode-animations'
import { cn } from '@/lib/utils'

export type SpinnerAnimation = keyof typeof spinners

interface FrameClock {
  subscribe: (listener: () => void) => () => void
  getFrame: () => number
}

const frameClocks = new Map<number, FrameClock>()

function frameClock(intervalMs: number): FrameClock {
  const existing = frameClocks.get(intervalMs)
  if (existing) return existing
  let frame = 0
  let timer: number | null = null
  const listeners = new Set<() => void>()
  const clock: FrameClock = {
    subscribe: (listener) => {
      listeners.add(listener)
      const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches
      if (timer === null && !reduceMotion) {
        timer = window.setInterval(() => {
          frame += 1
          for (const notify of listeners) notify()
        }, intervalMs)
      }
      return () => {
        listeners.delete(listener)
        if (listeners.size === 0 && timer !== null) {
          window.clearInterval(timer)
          timer = null
        }
      }
    },
    getFrame: () => frame,
  }
  frameClocks.set(intervalMs, clock)
  return clock
}

function serverFrame(): number {
  return 0
}

export function Spinner({ animation = 'braille', label = 'Loading', className }: { animation?: SpinnerAnimation; label?: string; className?: string }) {
  const { frames, interval } = spinners[animation]
  const clock = frameClock(interval)
  const frame = React.useSyncExternalStore(clock.subscribe, clock.getFrame, serverFrame)

  return (
    <span role="status" aria-label={label} data-slot="spinner" className={cn('inline-block font-mono leading-none select-none', className)}>
      {frames[frame % frames.length]}
    </span>
  )
}

export function EmptyState({
  icon: Icon,
  title,
  description,
  bordered = false,
  className,
  children,
}: {
  icon?: React.ComponentType<{ className?: string }>
  title?: React.ReactNode
  description?: React.ReactNode
  bordered?: boolean
  className?: string
  children?: React.ReactNode
}) {
  return (
    <div
      data-slot="empty-state"
      className={cn('flex flex-col items-center justify-center gap-2 p-6 text-center', bordered && 'rounded-lg border border-dashed', className)}
    >
      {Icon ? <Icon className="size-5 text-muted-foreground" /> : null}
      {title ? <p className="text-xs font-medium">{title}</p> : null}
      {description ? <p className="text-xs text-muted-foreground">{description}</p> : null}
      {children}
    </div>
  )
}

export function PanelCard({ className, children }: { className?: string; children: React.ReactNode }) {
  return <div className={cn('h-full min-h-0 overflow-hidden rounded-xl bg-card shadow-xs', className)}>{children}</div>
}

export function PanelHeader({ className, children }: { className?: string; children: React.ReactNode }) {
  return (
    <div data-slot="panel-header" className={cn('flex h-8 shrink-0 items-center gap-1 px-2', className)}>
      {children}
    </div>
  )
}

export const panelSectionLabelClass = 'text-2xs font-semibold tracking-wide text-muted-foreground uppercase'

export function PanelSectionLabel({ className, children }: { className?: string; children: React.ReactNode }) {
  return (
    <h4 data-slot="panel-section-label" className={cn(panelSectionLabelClass, className)}>
      {children}
    </h4>
  )
}

'use client'

import { useSyncExternalStore } from 'react'
import { toast } from 'sonner'
import {
  createLocalWhisperProvider,
  isLocalTranscriptionSupported,
  pickDefaultModel,
  WHISPER_MODELS,
  type LocalWhisperProgress,
} from '@mcut/transcription-local'
import type { TranscribeOptions, TranscriptResult } from '@mcut/transcription'

export { isLocalTranscriptionSupported }

const STORAGE_KEY = 'mcut:transcription:on-device:v1'

const listeners = new Set<() => void>()

function read(): boolean {
  if (typeof window === 'undefined') return false
  try {
    return window.localStorage.getItem(STORAGE_KEY) === '1'
  } catch {
    return false
  }
}

export function isOnDeviceTranscriptionEnabled(): boolean {
  return isLocalTranscriptionSupported() && read()
}

export function setOnDeviceTranscriptionEnabled(enabled: boolean): void {
  try {
    window.localStorage.setItem(STORAGE_KEY, enabled ? '1' : '0')
  } catch {}
  for (const listener of listeners) listener()
}

export function useOnDeviceTranscription(): boolean {
  return useSyncExternalStore(
    (onChange) => {
      listeners.add(onChange)
      return () => listeners.delete(onChange)
    },
    read,
    () => false,
  )
}

export function defaultModelDownloadLabel(): string {
  return pickDefaultModel() === WHISPER_MODELS.base ? '~145 MB' : '~40 MB'
}

let provider: ReturnType<typeof createLocalWhisperProvider> | null = null

const PROGRESS_TOAST_ID = 'mcut-on-device-transcription'

const ORT_WASM_FILES = { mjs: 'ort-wasm-simd-threaded.asyncify.mjs', wasm: 'ort-wasm-simd-threaded.asyncify.wasm' }

function ortWasmPaths(): { mjs: string; wasm: string } {
  return {
    mjs: new URL(`/ort/${ORT_WASM_FILES.mjs}`, window.location.origin).href,
    wasm: new URL(`/ort/${ORT_WASM_FILES.wasm}`, window.location.origin).href,
  }
}

function progressLabel(phase: LocalWhisperProgress['phase'], percent: number): string {
  if (phase === 'transcribe') return `Transcribing on this device… ${percent}%`
  return percent < 100 ? `Downloading Whisper model… ${percent}% (one-time, cached after this)` : 'Loading Whisper model…'
}

export async function transcribeOnDevice(audio: Blob, options?: TranscribeOptions): Promise<TranscriptResult> {
  provider ??= createLocalWhisperProvider({
    ortWasmPaths: ortWasmPaths(),
    onProgress: ({ phase, progress }) => {
      toast.loading(progressLabel(phase, Math.round(progress * 100)), { id: PROGRESS_TOAST_ID })
    },
  })
  try {
    return await provider.transcribe({ audio, mimeType: audio.type || 'audio/wav' }, options)
  } finally {
    toast.dismiss(PROGRESS_TOAST_ID)
  }
}

'use client'

import { toast } from 'sonner'
import { readDesktopApi, type DesktopErrorShape, type MenuAction } from '@mcut/desktop-ipc'
import { loadMediaBlob } from '@mcut/media'
import type { Project } from '@mcut/timeline'
import type { StudioHost } from './studio-host'

declare global {
  interface WindowEventMap {
    'mcut:run-action': CustomEvent<string>
  }
}

const MENU_ACTION_IDS: Record<MenuAction, string> = {
  'project.open': 'file.open',
  'project.save': 'file.save',
  'project.saveAs': 'file.save-as',
}

function reportFailure(error: DesktopErrorShape): void {
  if (error.code !== 'cancelled') toast.error(error.message)
}

async function relinkAssets(project: Project): Promise<{ project: Project; missing: number }> {
  let missing = 0
  const assets = { ...project.assets }
  for (const [id, asset] of Object.entries(assets)) {
    const blob = asset.hash ? await loadMediaBlob(asset.hash).catch(() => null) : null
    if (blob) {
      assets[id] = { ...asset, src: URL.createObjectURL(blob) }
      continue
    }
    if (asset.src.startsWith('blob:')) missing += 1
  }
  return { project: { ...project, assets }, missing }
}

export function createDesktopHost(): StudioHost | null {
  const api = readDesktopApi()
  if (api === null) return null
  const filePaths = new Map<string, string>()

  api.onMenu((action) => {
    window.dispatchEvent(new CustomEvent('mcut:run-action', { detail: MENU_ACTION_IDS[action] }))
  })

  const save = async (project: Project, path: string | null): Promise<void> => {
    const saved = await api.projects.save({ project, path })
    if (!saved.ok) return reportFailure(saved.error)
    filePaths.set(project.id, saved.value.path)
    toast.success(`Saved ${saved.value.path}`)
  }

  return {
    openProject: async (engine) => {
      const opened = await api.projects.open()
      if (!opened.ok) return reportFailure(opened.error)
      const { project, missing } = await relinkAssets(opened.value.project)
      engine.loadProject(project)
      filePaths.set(project.id, opened.value.path)
      if (missing > 0) {
        toast.warning(`${missing} media file(s) are not on this device. Re-import them to relink.`)
      } else {
        toast.success(`Opened ${project.name}`)
      }
    },
    saveProject: (project) => save(project, filePaths.get(project.id) ?? null),
    saveProjectAs: (project) => save(project, null),
    transcriptionSettings: {
      isConfigured: async () => {
        const info = await api.info()
        return info.ok && info.value.transcription.configured
      },
      setKey: async (key) => {
        const result = await api.setTranscriptionKey(key)
        if (!result.ok) {
          reportFailure(result.error)
          return false
        }
        return result.value.configured
      },
    },
    windowChrome: api.platform === 'darwin' ? 'mac' : 'linux',
  }
}

'use client'

import { toast } from 'sonner'
import { loadMediaBlob } from '@mcut/media'
import { parseProject, type EditorEngine, type Project } from '@mcut/timeline'
import { pickFiles } from './media-import'

function downloadText(text: string, filename: string, type: string) {
  const url = URL.createObjectURL(new Blob([text], { type }))
  const anchor = document.createElement('a')
  anchor.href = url
  anchor.download = filename
  anchor.click()
  setTimeout(() => URL.revokeObjectURL(url), 10_000)
}

export function saveProjectToFile(project: Project): void {
  const slug = (project.name || 'untitled').trim().replace(/[\\/:*?"<>|]+/g, '-')
  downloadText(JSON.stringify(project, null, 2), `${slug}.mcut.json`, 'application/json')
  toast.success('Project file saved — media re-links by content hash on this device')
}

export async function openProjectFromFile(engine: EditorEngine): Promise<void> {
  const [file] = await pickFiles('.json,application/json', false)
  if (!file) return
  let project: Project
  try {
    project = parseProject(JSON.parse(await file.text()))
  } catch (error) {
    console.error(error)
    toast.error(`${file.name} is not a valid mcut project file`)
    return
  }

  const missing: string[] = []
  const assets = { ...project.assets }
  for (const [id, asset] of Object.entries(assets)) {
    const blob = asset.hash ? await loadMediaBlob(asset.hash).catch(() => null) : null
    if (blob) {
      assets[id] = { ...asset, src: URL.createObjectURL(blob) }
    } else if (asset.src.startsWith('blob:')) {
      missing.push(id)
    }
  }

  engine.loadProject({ ...project, assets })
  if (missing.length > 0) {
    toast.warning(`${missing.length} media file(s) are not on this device — re-import them to relink.`)
  } else {
    toast.success(`Opened ${project.name}`)
  }
}

'use client'

import { toast } from 'sonner'
import { createAsset } from '@mcut/media'
import type { EditorEngine } from '@mcut/timeline'
import type { AssetRef } from '@mcut/timeline'

export type OnAssetImported = (asset: AssetRef, file: File) => void

export async function importMediaFiles(engine: EditorEngine, files: File[], onAssetImported?: OnAssetImported): Promise<AssetRef[]> {
  const imported: AssetRef[] = []
  for (const file of files) {
    try {
      const asset = await createAsset({ kind: 'blob', blob: file, name: file.name })
      engine.dispatch({ type: 'addAsset', asset }, { history: false })
      imported.push(asset)
      onAssetImported?.(asset, file)
    } catch (error) {
      console.error(error)
      toast.error(`Could not import ${file.name}`)
    }
  }
  return imported
}

export function pickFiles(accept: string, multiple = true): Promise<File[]> {
  return new Promise((resolve) => {
    const input = document.createElement('input')
    input.type = 'file'
    input.accept = accept
    input.multiple = multiple
    input.onchange = () => resolve(Array.from(input.files ?? []))
    input.oncancel = () => resolve([])
    input.click()
  })
}
